import { IsInt, IsString, IsUUID, Length, Max, Min } from 'class-validator';

export class ReserveNumberBlockDto {
  @IsUUID()
  branch_id!: string;

  // Capped at 200 so a single device can't reserve the whole day's numbering
  // and leave a huge gap if it never consumes the range.
  @IsInt()
  @Min(1)
  @Max(200)
  size!: number;

  // Opaque per-browser id generated by the client, so reopening the POS gets
  // the same range back instead of burning a new one on every reload.
  @IsString()
  @Length(8, 64)
  device_id!: string;
}
